const $=id=>document.getElementById(id), BASE='https://resultados.tse.jus.br/oficial/ele2026/6258/';
const states=[['ac','Acre'],['al','Alagoas'],['ap','Amapá'],['am','Amazonas'],['ba','Bahia'],['ce','Ceará'],['df','Distrito Federal'],['es','Espírito Santo'],['go','Goiás'],['ma','Maranhão'],['mt','Mato Grosso'],['ms','Mato Grosso do Sul'],['mg','Minas Gerais'],['pa','Pará'],['pb','Paraíba'],['pr','Paraná'],['pe','Pernambuco'],['pi','Piauí'],['rj','Rio de Janeiro'],['rn','Rio Grande do Norte'],['rs','Rio Grande do Sul'],['ro','Rondônia'],['rr','Roraima'],['sc','Santa Catarina'],['sp','São Paulo'],['se','Sergipe'],['to','Tocantins']];
let tab='geral',uf='sp',city='',locations=[],data=null,requestId=0,currentURL='',busy=false;
const num=x=>Number(String(x??0).replace(',','.')), fmt=x=>num(x).toLocaleString(uiLocale()), pct=x=>num(x).toLocaleString(uiLocale(),{minimumFractionDigits:2,maximumFractionDigits:2})+'%';
const safe=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function title(x){return x.toLocaleLowerCase('pt-BR').replace(/(^|\s)\S/g,c=>c.toLocaleUpperCase('pt-BR'));}
function getScope(){if(tab==='totalizacao')return translateText('Votação após as 17h');if(tab==='geral')return translateText('Brasil + exterior');if(city)return title((locations.find(a=>a.cd.toLowerCase()===uf)?.mu||[]).find(m=>m.cd===city)?.nm||city);return uf==='zz'?translateText('Exterior'):states.find(s=>s[0]===uf)?.[1]||uf.toUpperCase();}
function candidateList(d){return (d.carg||[]).filter(c=>c.cd==='1').flatMap(c=>(c.agr||[]).flatMap(a=>(a.par||[]).flatMap(p=>(p.cand||[]).map(c=>({...c,party:p.sg}))))).sort((a,b)=>num(b.vap)-num(a.vap)||num(a.n)-num(b.n));}
function clearView(){data=null;$('post17-total').textContent='—';$('post17-date').textContent=translateText('Aguardando arquivo divulgado após as 17h.');$('election-summary').innerHTML='';$('scope').textContent=getScope();$('candidates').innerHTML=localizeHTML('<div class="loading">Consultando dados desta localidade…</div>');$('status').textContent=translateText('Consultando');['total','valid','blank','nulls','absent','percent'].forEach(id=>$(id).textContent='—');$('sections').textContent=translateText('— / —');$('progress').style.width='0';$('generated').textContent=translateText('Fonte: TSE');$('download').disabled=true;}
async function update(){if(tab==='totalizacao'){return updateAfterHours();}const id=++requestId;busy=true;$('refresh').disabled=true;const region=isNationalTab(tab)?'br':uf;const url=BASE+`dados/${region}/${region}${city}-c0001-e006258-u.json`;currentURL=url;clearView();$('notice').className='notice';$('notice').textContent=translateText('Consultando arquivos oficiais do TSE…');try{const res=await fetch(url,{signal:AbortSignal.timeout(15000)});if(!res.ok)throw Error('HTTP '+res.status);const d=await res.json();if(id!==requestId)return;validateElectionData(d,{region,city});data=d;render(d);$('download').disabled=false;const time=new Date().toLocaleTimeString(uiLocale(),{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',second:'2-digit'});$('checked').textContent=translateText('Consulta às '+time);let status=d.and==='f'?'Totalização encerrada':d.and==='p'?'Apuração em andamento':'Aguardando apuração';$('status').textContent=translateText(electionResult(d).winner?electionResult(d).heading:status);$('notice').textContent=translateText(d.and==='n'?'Aguardando o início da totalização. Os arquivos do TSE ainda não registram votos nesta abrangência. Divulgação a partir das 17h de Brasília.':`Dados oficiais do TSE · ${status}. Os números refletem a última geração do arquivo, indicada abaixo.`);}catch(e){if(id!==requestId)return;$('status').textContent=translateText('Dados indisponíveis');$('notice').className='notice error';$('notice').textContent=translateText('Não foi possível consultar os dados desta localidade agora. Tente atualizar ou acesse os resultados oficiais do TSE.');$('candidates').innerHTML=localizeHTML('<div class="loading">Nenhum resultado carregado.<br><br>Use o botão ↻ para tentar novamente.</div>');$('checked').textContent=translateText('Consulta não concluída');}finally{if(id===requestId){busy=false;$('refresh').disabled=false;}}}
function render(d){$('total').textContent=countedVotes(d)===null?'—':fmt(countedVotes(d));$('total-note').textContent=translateText(totalsReleased()?'Válidos, brancos e nulos':'Disponível a partir das 17h de Brasília');$('election-summary').innerHTML=outcomeHTML(d)+voteMarginHTML(d);$('percent').textContent=pct(d.s.pst);$('sections').textContent=fmt(d.s.st)+' / '+fmt(d.s.ts);$('progress').style.width=Math.min(100,Math.max(0,num(d.s.pst)))+'%';$('valid').textContent=fmt(d.v.vv);$('blank').textContent=fmt(d.v.vb);$('nulls').textContent=fmt(d.v.tvn??d.v.vn);$('absent').textContent=fmt(d.e?.a);$('generated').textContent=translateText(`Arquivo TSE: ${d.dg} · ${d.hg} (Brasília)`);$('candidates').innerHTML=candidateList(d).map(c=>`<div class="candidate"><div class="avatar" aria-hidden="true" style="color:${candidateColor(c.n,d)};background:color-mix(in srgb, ${candidateColor(c.n,d)} 10%, white)">${safe(c.n)}</div><div><h3>${safe(title(c.nmu||c.nm))}</h3><p>${safe(c.party)} · ${safe(c.n)}${electionResult(d).winner?.n===c.n?' · Eleito segundo o TSE':''}</p><div class="vote-bar"><span style="width:${Math.min(100,Math.max(0,num(c.pvap)))}%;background:${candidateColor(c.n,d)}"></span></div></div><div class="vote-result"><b>${pct(c.pvap)}</b><small>${fmt(c.vap)} votos</small></div></div>`).join('');$('candidates').innerHTML=localizeHTML($('candidates').innerHTML);}
function fillCities(){const list=locations.find(a=>a.cd.toLowerCase()===uf)?.mu||[];$('city').innerHTML='<option value="">'+translateText(uf==='zz'?'Todo o exterior':'Todo o estado')+'</option>'+list.map(m=>`<option value="${safe(m.cd)}">${safe(title(m.nm))}</option>`).join('');$('city').value=city;}
function setTab(next,nextUF,nextCity=''){tab=next;uf=next==='exterior'?'zz':nextUF||'sp';city=nextCity;document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===tab)));$('painel').dataset.view=tab;$('filters').hidden=isNationalTab(tab)||tab==='totalizacao';$('totalization-info').hidden=tab!=='totalizacao';$('uf').parentElement.hidden=tab==='exterior';$('uf').value=uf;fillCities();document.querySelectorAll('#states button').forEach(b=>b.classList.toggle('selected',tab==='brasil'&&b.dataset.uf===uf));update();}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));$('uf').innerHTML=states.map(([cd,nm])=>`<option value="${cd}">${nm}</option>`).join('');$('states').innerHTML=states.map(([cd,nm])=>`<button data-uf="${cd}" title="Consultar ${nm}">${cd.toUpperCase()}</button>`).join('');document.querySelectorAll('#states button').forEach(b=>b.onclick=()=>{setTab('brasil',b.dataset.uf);$('painel').scrollIntoView({behavior:'smooth'});});$('uf').onchange=()=>setTab('brasil',$('uf').value);$('city').onchange=()=>{city=$('city').value;update();};$('refresh').onclick=update;$('explore').onclick=()=>setTab('exterior');
function search(){const q=$('search').value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const list=(locations.find(a=>a.cd.toLowerCase()==='zz')?.mu||[]).filter(m=>m.nm.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q));$('search-results').innerHTML=list.slice(0,q?30:5).map(m=>`<button data-city="${safe(m.cd)}">${safe(title(m.nm))} ↗</button>`).join('')||'<span style="font-size:11px;color:#76817a">Nenhuma localidade encontrada.</span>';$('search-results').innerHTML=localizeHTML($('search-results').innerHTML);$('search-results').querySelectorAll('button').forEach(b=>b.onclick=()=>{setTab('exterior','zz',b.dataset.city);$('painel').scrollIntoView({behavior:'smooth'});});}
$('search').oninput=search;$('download').onclick=()=>{if(tab==='totalizacao'){downloadAfterHours();return;}if(!data)return;const blob=new Blob([JSON.stringify({fonte:currentURL,consultadoEm:new Date().toISOString(),dados:data},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='tse-2026-segundo-turno-'+(isNationalTab(tab)?'br':uf+city)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);};
async function init(){try{const r=await fetch('localidades.json');if(!r.ok)throw Error();locations=(await r.json()).abr;$('foreign-count').textContent=locations.find(a=>a.cd.toLowerCase()==='zz')?.mu.length||'—';fillCities();search();}catch(e){$('search-results').textContent=translateText('Cadastro de localidades indisponível.');}update();}setInterval(()=>{if($('auto').checked&&!document.hidden&&!busy)update();},60000);init();

window.addEventListener('languagechange',()=>{fillCities();search();document.querySelectorAll('#states button').forEach(b=>b.title=translateText('Consultar '+states.find(s=>s[0]===b.dataset.uf)[1]));update();});


$('late-download').onclick=downloadAfterHours;
for(const anchor of document.querySelectorAll('nav a[href="#mapa"],nav a[href="#localidades"],nav a[href="#fontes"]'))anchor.addEventListener('click',()=>{if(tab==='totalizacao')setTab('geral');});
